#set page(width: 595pt, height: 842pt, margin: 28pt)

#set text(font: "New Computer Modern", size: 16pt)

#set par(justify: true, leading: 0.6em)

#set align(horizon)

#let diagram = cetz.canvas({
  import cetz.draw: *
  import cetz.vector: sub, add, scale, normalize

  // Zig-zag resistor drawn along the segment a->b.
  // Splits the segment into two short leads and a centred zig-zag.
  let resistor(a, b, n: 6, amp: 0.18, lead: 0.25) = {
    let d = sub(b, a)
    let L = calc.sqrt(d.at(0) * d.at(0) + d.at(1) * d.at(1))
    let ux = d.at(0) / L
    let uy = d.at(1) / L
    // perpendicular unit vector (left-hand normal)
    let nx = -uy
    let ny = ux

    let p0 = a
    let p1 = add(a, (ux * lead * L, uy * lead * L))
    let p2 = add(b, (-ux * lead * L, -uy * lead * L))
    let p3 = b

    line(p0, p1, stroke: black + 1.6pt)

    // zig-zag from p1 to p2 with (n+1) interior points alternating up/down
    let pts = ()
    let span = 1 - 2 * lead           // fraction of L occupied by zig-zag
    let step = span / (n + 1)
    let start-t = lead
    let up = true
    for i in range(1, n + 2) {
      let t = lead + step * i
      let base = add(p1, (ux * (t - lead) * L, uy * (t - lead) * L))
      let sgn = if calc.rem(i, 2) == 1 { 1 } else { -1 }
      let peak = if i == 1 or i == n + 1 {
        base   // ends sit on the line so the leads connect smoothly
      } else {
        add(base, (nx * amp * sgn, ny * amp * sgn))
      }
      pts.push(peak)
    }
    line(p1, ..pts, p2, stroke: black + 1.6pt)

    line(p2, p3, stroke: black + 1.6pt)
  }

  let A = (0, 3)
  let P = (-3, 0)
  let B = (0, -3)
  let Q = (3, 0)
  let M = (0, 0)

  // 7 resistors (one per edge)
  resistor(A, P)
  resistor(A, Q)
  resistor(P, B)
  resistor(Q, B)
  resistor(P, Q)
  resistor(A, M)
  resistor(M, B)

  // Junction dots at every node
  for n in (A, P, B, Q, M) {
    circle(n, radius: 2.2pt, fill: black, stroke: none)
  }

  // Vertex labels (anchor is the side of the label placed at the point,
  // so use the opposite side to push the label away from the circuit)
  content(A, [#text(red)[$A$]], anchor: "south", padding: 6pt)
  content(B, [#text(red)[$B$]], anchor: "north", padding: 6pt)
  content(P, [#text(black)[$P$]], anchor: "east", padding: 6pt)
  content(Q, [#text(black)[$Q$]], anchor: "west", padding: 6pt)
  content(M, [#text(black)[$M$]], anchor: "south-west", padding: 4pt)
})

