input.new_string:
let A = (0, 3)
let P = (-3, 0)
let B = (0, -3)
let Q = (3, 0)
let M = (0, 0)

// 6 inline resistors (diamond sides + A-M and M-B segments).
// The PQ bridge is drawn separately so it can pass over AB without
// connecting at M.
resistor(A, P)
resistor(A, Q)
resistor(P, B)
resistor(Q, B)
resistor(A, M)
resistor(M, B)

// --- PQ bridge with the resistor inline, hopping over AB ---
// Two leads join P and Q to a centred rectangle; the AB line gets a
// small "no-connect" bump at the crossing to show the wires do not
// touch.

// Place the PQ resistor a bit above the PQ line so it does not
// overlap the rectangle drawn for A-M or M-B.
let bridge-h = 0.55   // perpendicular offset of the rectangle above PQ
let box-len = 3.0     // along PQ
let box-w = 0.32
// centre of the rectangle (lifted above PQ)
let cm = (0, bridge-h)
// along-PQ unit vector (+x) and normal (+y)
let ux = 1.0
let ny = 1.0
let nx = 0.0
let e1 = add(cm, (-ux * box-len / 2, -ny * bridge-h))
let e2 = add(cm, (ux * box-len / 2, -ny * bridge-h))

// Smooth leads from P->e1 and e2->Q (two cubic arcs each).
// Anchor points just outside the box ends so the arcs bend up cleanly.
let p-in = add(e1, (-0.15, 0))
let q-in = add(e2, (0.15, 0))
line(P, p-in, stroke: black + 1.6pt)
bezier-through(P, (calc.mid(P.at(0), e1.at(0)), calc.max(P.at(1), e1.at(1) + 0.6)), e1, p-in, stroke: black + 1.6pt)
// the above won't actually draw; we'll use bezier instead.
// Reset and use proper bezier curves:
// (removed by the loop below)

// -- Replace with a clean version: two cubic Bezier leads + rectangle --
// Use the canvas `bezier` function with an explicit control scheme.

// First, draw the rectangle box (white-fill so it occludes anything beneath).
let bc1 = add(cm, (-ux * box-len / 2, -ny * box-w))
let bc2 = add(cm, (ux * box-len / 2, -ny * box-w))
let bc3 = add(cm, (ux * box-len / 2, ny * box-w))
let bc4 = add(cm, (-ux * box-len / 2, ny * box-w))
line(bc1, bc2, bc3, bc4, close: true, stroke: black + 1.6pt, fill: white)

// Leads from P and Q up into the rectangle (smooth cubic curves).
bezier(P, (P.at(0), bridge-h + box-w), (e1.at(0) - 0.6, bridge-h + box-w), e1, stroke: black + 1.6pt)
bezier(Q, (Q.at(0), bridge-h + box-w), (e2.at(0) + 0.6, bridge-h + box-w), e2, stroke: black + 1.6pt)

// Bump on AB where the PQ bridge crosses (cosmetic "no-connect").
// Two little half-arcs centered at M with the segment passing under.
// We do this by erasing the AB line near M and replacing it with two arcs.
// Simple, robust approach: draw a tiny white disc at M (to hide the AB
// crossing) then two small arcs on the right side of the bump.
// Cleaner alternative: redraw the AB wire below the crossing as two arcs.
// We'll use the latter.

// Hide the straight AB under the bump by drawing a small white rectangle
// then drawing the bridge semicircles around it.
let bump-half-w = 0.55
let bump-half-h = 0.18
// white background patch
line(
  add(M, (-bump-half-w, -bump-half-h)),
  add(M, ( bump-half-w, -bump-half-h)),
  add(M, ( bump-half-w,  bump-half-h)),
  add(M, (-bump-half-w,  bump-half-h)),
  close: true, fill: white, stroke: none,
)
// Vertical lead of AB from below the patch up to the patch bottom
line(add(M, (0, -3)), add(M, (0, -bump-half-h)), stroke: black + 1.6pt)
// Bump arc right
arc(
  add(M, (0, 0)), start: -90deg + 0deg, stop: 90deg + 0deg,
  radius: bump-half-w, anchor: "origin",
  mode: "PIE",
)
// Bump arc going back (we'll instead compose with two arcs)
// Simplify: draw the full AB path broken into three pieces.
// Clear by overdrawing:
//   left semicircle from below to top, then right semicircle back down.
// For cetz.arc, easiest is two arcs starting/ending at the patch edges.
let above = add(M, (0, bump-half-h))
let below = add(M, (0, -bump-half-h))
// left hump
arc(
  M, start: 90deg, stop: 180deg, radius: bump-half-w,
  anchor: "origin", mode: "OPEN",
  stroke: black + 1.6pt,
)
// right hump
arc(
  M, start: 0deg, stop: 90deg, radius: bump-half-w,
  anchor: "origin", mode: "OPEN",
  stroke: black + 1.6pt,
)

// Junction dots only at the actual nodes (not at M, because the PQ
// bridge hops over AB and does not connect there).
for n in (A, P, B, Q) {
  circle(n, radius: 2.2pt, fill: black, stroke: none)
}
// small open ring at M to show it is a labelled node on AB but NOT
// joined to the PQ bridge.
circle(M, radius: 2.2pt, fill: white, stroke: black + 1pt)

