input.contents:
#import "@preview/cetz:0.5.2"

#let diagram = cetz.canvas({
  import cetz.draw: *
  import cetz.vector: sub, add

  // IEC-style rectangle resistor drawn along the segment a->b.
  // Splits the segment into two short leads and a centred box.
  let resistor(a, b, box-frac: 0.42, half-w: 0.32) = {
    let d = sub(b, a)
    let L = calc.sqrt(d.at(0) * d.at(0) + d.at(1) * d.at(1))
    let ux = d.at(0) / L
    let uy = d.at(1) / L
    // perpendicular unit vector (left-hand normal)
    let nx = -uy
    let ny = ux

    let half-len = box-frac * L / 2
    let mid = add(a, (ux * L / 2, uy * L / 2))
    // box end-points along the axis
    let e1 = add(mid, (-ux * half-len, -uy * half-len))
    let e2 = add(mid, (ux * half-len, uy * half-len))

    // leads
    line(a, e1, stroke: black + 1.6pt)
    line(e2, b, stroke: black + 1.6pt)

    // rectangle corners (e1/e2 offset perpendicular by +/- half-w)
    let c1 = add(e1, (nx * half-w, ny * half-w))
    let c2 = add(e2, (nx * half-w, ny * half-w))
    let c3 = add(e2, (-nx * half-w, -ny * half-w))
    let c4 = add(e1, (-nx * half-w, -ny * half-w))
    line(c1, c2, c3, c4, close: true, stroke: black + 1.6pt, fill: white)
  }

  let A = (0, 3)
  let P = (-3, 0)
  let B = (0, -3)
  let Q = (3, 0)
  let M = (0, 0)

  // 6 inline resistors (diamond sides + A-M and M-B segments).
  // The PQ branch is drawn separately so it can hop over AB without
  // connecting at M.
  resistor(A, P)
  resistor(A, Q)
  resistor(P, B)
  resistor(Q, B)
  resistor(A, M)
  resistor(M, B)

  // --- PQ branch: a single resistor that hops over the AB wire ---
  // The AB diameter is continuous; PQ passes OVER it via a small
  // semicircular bridge (the standard "wires cross, no connection"
  // symbol), and the PQ resistor sits inline just to the right of the
  // hop.
  let r-hop = 0.42   // radius of the bridge hop over AB

  // Left lead from P up to the left foot of the hop.
  line(P, (-r-hop, 0), stroke: black + 1.6pt)
  // Semicircular hop over the AB wire (from the right foot, over the top,
  // to the left foot). anchor "origin" => M is the arc centre.
  arc(
    M, start: 0deg, stop: 180deg, radius: r-hop,
    anchor: "origin", mode: "OPEN", stroke: black + 1.6pt,
  )
  // Right of the hop: the PQ resistor inline, running to Q.
  resistor((r-hop, 0), Q)

  // Junction dots at the real nodes. M is the series junction of the two
  // AB resistors, so it is a genuine node on AB (filled dot); the PQ hop
  // passes above it without touching.
  for n in (A, P, B, Q, M) {
    circle(n, radius: 2.2pt, fill: black, stroke: none)
  }

  // Vertex labels (anchor is the side of the label placed at the point,
  // so use the opposite side to push the label away from the circuit)
  content(A, [#text(red)[$A$]], anchor: "south", padding: 6pt)
  content(B, [#text(red)[$B$]], anchor: "north", padding: 6pt)
  content(P, [#text(black)[$P$]], anchor: "east", padding: 6pt)
  content(Q, [#text(black)[$Q$]], anchor: "west", padding: 6pt)
  content(M, [#text(black)[$M$]], anchor: "south-west", padding: 4pt)
})

// Multiple-choice grid. Pass e.g. answer: "B" to highlight the key.
#let choices(answer: none) = {
  let mark(label, body) = if answer == label {
    text(fill: rgb("#1a7f37"))[*#label) #h(0.6em) #body*]
  } else {
    [#label) #h(0.6em) #body]
  }
  set text(size: 16pt)
  grid(
    columns: (1fr, 1fr),
    column-gutter: 18pt,
    row-gutter: 18pt,
    align: (left + horizon),
    mark("A", $R_(eq) = R \/ 2$),
    mark("B", $R_(eq) = 2 R \/ 3$),
    mark("C", $R_(eq) = 5 R \/ 6$),
    mark("D", $R_(eq) = R$),
  )
}

#let statement(answer: none) = block(width: 100%)[
  The diagram shows a planar network of $7$ identical resistors, each of
  resistance $R$: a diamond $A P B Q A$ with the horizontal diagonal $P Q$
  and the vertical diameter $A M B$ drawn through a central node $M$.

  #v(8pt)

  Find the equivalent resistance $R_(eq)$ measured between the two
  opposite vertices $A$ and $B$ of the diamond.

  #v(14pt)

  #choices(answer: answer)
]

#let solution = block(width: 100%)[
  #line(length: 100%, stroke: 0.6pt + gray)

  #v(2pt)

  *Solution — answer B: #h(0.4em) $R_(eq) = 2R \/ 3$.*

  #v(4pt)

  *Symmetry.* Drive a current in at $A$ and out at $B$. Reflecting the
  network in the vertical axis $A M B$ maps the circuit onto itself while
  swapping the two side nodes $P arrow.l.r Q$. The driving terminals $A$, $B$
  lie on the axis, so they are unchanged. Hence $P$ and $Q$ sit at the same
  potential:
  $ V_P = V_Q. $

  *Drop the bridge.* Because its two ends are at equal potential, the
  diagonal resistor $P Q$ carries no current and can be removed without
  changing anything.

  *Three parallel branches.* What remains are three independent paths from
  $A$ to $B$, each a pair of resistors in series:
  $ A -> P -> B: 2R, quad A -> Q -> B: 2R, quad A -> M -> B: 2R. $

  These three $2R$ branches are in parallel:
  $ 1 / R_(eq) = 1 / (2R) + 1 / (2R) + 1 / (2R) = 3 / (2R)
    quad => quad R_(eq) = (2R) / 3. $
]

#import "@preview/cetz:0.5.2"

// Main setup: top-down view of a student, mirror, and a horizontal card with
// the word "HIDE" held facing the mirror. The dashed grey lines are
// "back-traced" reflected rays: a viewer standing where the student is, whose
// eyes are in front of the mirror, sees the card through the mirror and
// mentally extends the rays to the other side, placing the virtual image on
// the opposite side of the glass. Crucially, the card is held HORIZONTAL
// (not perpendicular to the student's line of sight), so the text in the
// image is rotated 180° about the axis perpendicular to the page, not
// left-right flipped.
#let setup = cetz.canvas({
  import cetz.draw: *

  // Floor / optical axis (the line from student to mirror)
  line((-5.0, 0), (4.5, 0), stroke: (dash: "dashed", paint: gray))

  // Student (oval head viewed from above + small body) on the left
  let x-student = -3.5
  circle((x-student, 0.0), radius: 0.55, stroke: 1.4pt, fill: white)
  // Arms extending forward (toward the mirror) holding the card
  line((x-student + 0.45, -0.05), (x-student + 1.7, -0.05), stroke: 1.2pt)
  line((x-student + 0.45, 0.05), (x-student + 1.7, 0.05), stroke: 1.2pt)
  content((x-student, -0.9), text(size: 14pt)[student])

  // Mirror (vertical bar) on the right
  let x-mirror = 2.0
  line((x-mirror, -1.8), (x-mirror, 1.8), stroke: 2.2pt)
  // Hash marks on the FAR side of the mirror (the reflective side faces the student)
  for dy in range(-6) {
    let yy = -1.5 + dy * 0.5
    line((x-mirror + 0.3, yy), (x-mirror, yy + 0.2), stroke: 0.8pt)
  }
  content((x-mirror, -2.1), text(size: 14pt)[mirror])

  // Card (a long thin rectangle) held horizontally in front of the student,
  // oriented parallel to the student's line of sight (i.e. perpendicular to
  // the mirror). The text reads left->right along the card and faces the
  // mirror (i.e. faces +x, away from the student).
  let x-card-front = x-student + 1.7
  let x-card-back = x-student + 0.7
  let card-y-half = 0.35
  // Card outline
  line(
    (x-card-back, -card-y-half),
    (x-card-front, -card-y-half),
    (x-card-front, card-y-half),
    (x-card-back, card-y-half),
    close: true,
    stroke: 1.4pt,
    fill: white,
  )
  // Word "HIDE" written along the card (left->right, normal orientation)
  // Each letter as a small block; we'll just label the card instead for clarity
  content(
    ((x-card-back + x-card-front) / 2, 0.0),
    text(size: 16pt, weight: "bold")[H I D E],
  )
  content((x-card-back - 0.1, 0.0), anchor: "east", text(size: 12pt)[card])

  // Two reflected rays (a ray from the card tip going to the mirror and
  // reflecting to the student's eye). We trace a ray from the LEFT end of
  // the card (which, in the image, is on the right) going back to the eye.
  // For simplicity we just draw the geometric construction lines.
  let eye = (x-student + 0.55, 0.05)
  // Ray from a point on the card surface to the mirror, then reflected back
  // to the eye. Pick point near the right end of the card on the top edge:
  let card-top-right = (x-card-front, card-y-half)
  line(card-top-right, (x-mirror, card-y-half), stroke: 1.0pt, paint: gray)
  line((x-mirror, card-y-half), eye, stroke: 1.0pt, paint: gray)

  // Virtual-image back-trace: extend the reflected ray on the OTHER side of
  // the mirror by the same length. This shows where the brain "places" the
  // image of the card.
  let incident-dx = x-mirror - card-top-right.at(0)
  let incident-dy = 0.0
  let reflected-dx = x-mirror - eye.at(0)
  let reflected-dy = eye.at(1) - x-mirror * 0  // eye is at y~0; line slope preserved
  // Back-traced ray: start at the mirror at the reflection point, go in the
  // direction opposite the incident ray, for the same length as the
  // reflected ray.
  let back-start = (x-mirror, card-y-half)
  let back-end = (x-mirror + reflected-dx, card-y-half - reflected-dy)
  line(back-start, back-end, stroke: (dash: "dotted", paint: gray))

  // The virtual image of the card sits at the back-trace end (roughly)
  content(
    ((x-mirror + 3.0) / 1 + 0.0, 0.7),
    text(size: 13pt, fill: rgb("#666"))[#emph[virtual image of card]],
  )
})

// Four small diagrams, one per option. Each shows a top-view of the student
// and mirror, with the IMAGE of the word as the student would see it. The
// images are drawn with letter-glyphs to keep them readable.
#let opt-diagram(kind) = cetz.canvas({
  import cetz.draw: *

  // Optical axis
  line((-2.6, 0), (2.6, 0), stroke: (dash: "dashed", paint: gray))

  // Mirror on the right
  let x-mirror = 2.0
  line((x-mirror, -1.4), (x-mirror, 1.4), stroke: 1.8pt)
  for dy in range(-5) {
    let yy = -1.2 + dy * 0.5
    line((x-mirror + 0.3, yy), (x-mirror, yy + 0.2), stroke: 0.7pt)
  }

  // Real card on the student side (always drawn the same way for reference)
  let x-card-front = -0.5
  let x-card-back = -1.5
  line(
    (x-card-back, -0.3),
    (x-card-front, -0.3),
    (x-card-front, 0.3),
    (x-card-back, 0.3),
    close: true,
    stroke: 1.2pt,
    fill: white,
  )
  content(
    ((x-card-back + x-card-front) / 2, 0),
    text(size: 11pt, weight: "bold")[HIDE],
  )

  // Image of the card on the OTHER side of the mirror
  let xi-front = 2 * x-mirror - x-card-front
  let xi-back = 2 * x-mirror - x-card-back
  // 180° rotation about the mirror axis: top<->bottom AND left<->right
  // (i.e. the card is mirrored to the right, and "flipped upside-down" in
  // the page-plane sense). The text inside also rotates with the card.
  let img-y = -0.0  // vertical position on the image side
  let img-card = (
    (xi-back, img-y - 0.3),
    (xi-front, img-y - 0.3),
    (xi-front, img-y + 0.3),
    (xi-back, img-y + 0.3),
  )
  let stroke = if kind == "none" or kind == "rot" {
    (paint: red, dash: "dashed", thickness: 1.4pt)
  } else {
    (paint: red, dash: "dashed", thickness: 1.4pt)
  }
  line(
    img-card.at(0),
    img-card.at(1),
    img-card.at(2),
    img-card.at(3),
    close: true,
    stroke: 1.4pt,
    fill: white,
  )

  // Word in the image, depending on option
  let img-label = none
  if kind == "all-flipped" {
    // Option A: every letter reversed
    img-label = [#text(size: 11pt, weight: "bold")[Ǝ◖Iꟻ]]
  } else if kind == "hi-flipped" {
    // Option B: only H and I reversed (vertical-axis symmetry myth)
    img-label = [#text(size: 11pt, weight: "bold")[IꟻED]]
  } else if kind == "de-flipped" {
    // Option C: only D and E reversed (asymmetric letters myth)
    img-label = [#text(size: 11pt, weight: "bold")[HIDƎ]]
  } else if kind == "none" {
    // Option D: nothing reversed
    img-label = [#text(size: 11pt, weight: "bold")[HIDE]]
  }
  if img-label != none {
    content(((xi-back + xi-front) / 2, img-y), img-label)
  }
})

// All four option diagrams in a 2x2 grid, labelled
#let option-grid() = grid(
  columns: (1fr, 1fr),
  column-gutter: 12pt,
  row-gutter: 8pt,
  align: (center, center),
  [
    #opt-diagram("all-flipped")
    #text(size: 13pt)[A) all four reversed]
  ],
  [
    #opt-diagram("hi-flipped")
    #text(size: 13pt)[B) only H and I reversed]
  ],
  [
    #opt-diagram("de-flipped")
    #text(size: 13pt)[C) only D and E reversed]
  ],
  [
    #opt-diagram("none")
    #text(size: 13pt)[D) none reversed]
  ],
)

// Multiple-choice answers. Pass answer: "D" to highlight D.
#let choices(answer: none) = {
  let mark(label, body) = if answer == label {
    text(fill: rgb("#1a7f37"))[*#label) #h(0.6em) #body*]
  } else {
    [#label) #h(0.6em) #body]
  }
  set text(size: 16pt)
  grid(
    columns: (1fr, 1fr),
    column-gutter: 18pt,
    row-gutter: 14pt,
    align: (left + horizon),
    mark("A", [all four letters are reversed]),
    mark("B", [only H and I are reversed]),
    mark("C", [only D and E are reversed]),
    mark("D", [none of the letters are reversed]),
  )
}

#let statement(answer: none) = block(width: 100%)[
  A student stands facing a flat vertical mirror. She holds a small card in
  front of her chest, *horizontal* (parallel to the floor), with the word
  #text(weight: "bold")[HIDE] written on it in capital letters. The text is
  oriented in the usual way (readable left-to-right by someone standing
  behind her) and faces the mirror.

  #v(8pt)

  Looking at the mirror, which letters of the word appear reversed
  ("laterally inverted") to her?

  #v(14pt)

  #choices(answer: answer)
]

#let solution = block(width: 100%)[
  #line(length: 100%, stroke: 0.6pt + gray)

  #v(2pt)

  *Solution — answer D: #h(0.4em) none of the letters are reversed.*

  #v(6pt)

  *What a flat mirror actually does.* A flat mirror reflects along the
  normal to its surface — i.e. along the axis perpendicular to the glass.
  Every point on the object has a mirror-image point at the same distance
  on the far side of the glass, with left/right and up/down both swapped
  (because the far-side point has its back facing the observer).

  #v(4pt)

  *Apply it to the card.* The card is a small rectangle lying in a plane
  parallel to the mirror. Every point on the card has a corresponding
  point on the virtual card, on the far side of the mirror, with the
  *front of the card now facing away* from the student. Look at the image
  from behind, and the text reads in the natural direction again:

  $ "HIDE" arrow.l.r "HIDE" $

  #v(4pt)

  *Where does "left-right reversal" come from, then?* The brain has to
  *turn the observer* (or the head) by 180° in the page plane in order to
  read the image straight-on. That rotation, *imposed by the observer's
  change of perspective*, is what makes the text appear left-right
  swapped. It is not a property of the mirror; it is a property of how
  we choose to view the reflected scene.

  #v(4pt)

  *Concretely:* if the card had been vertical and facing her (not the
  mirror), then the "rotate to read" step would have rotated the text by
  180° in the page plane, making "HIDE" read as #emph[Ǝ◖Iꟻ] — but only
  *because the student chose to turn around to face it*. The mirror just
  built a behind-the-glass twin; the perceived left-right flip is the
  observer's doing.
]

