    // Engine torque spins the wheel so the contact patch tends to push
    // BACKWARD on the road; road pushes tire FORWARD.
    // Torque arrow (curved, clockwise = forward drive)
    arc((0.0, 0.55), start: 130deg, stop: -10deg, radius: 0.55,
      mark: (end: ">"), stroke: 1.6pt + rgb("#8e44ad"))
    content((0.9, 0.7), text(size: 12pt, fill: rgb("#8e44ad"))[$tau$])

    // "tends to slip backward" small grey arrow at contact
    line(cp, (cp.at(0) - 0.7, -R), mark: (end: ">"),
      stroke: 1pt + gray)
    content((-0.75, -R - 0.28), anchor: "east",
      text(size: 10pt, fill: gray)[slip tendency])

    // friction forward
    line(cp, (cp.at(0) + 1.1, -R), mark: (end: ">"),
      stroke: 2pt + rgb("#1a7f37"))
    content((1.15, -R + 0.28), anchor: "west",
      text(size: 13pt, fill: rgb("#1a7f37"))[$f$])
  } else {
    // Rolling wheel is dragged forward by the axle; contact patch tends to
    // slip FORWARD, so road friction acts BACKWARD (small, decelerating spin).
    line((0, R + 0.35), (0, R + 0.05), mark: (end: ">"),
      stroke: 1pt + gray)
    line((0.05, R + 0.35), (0.75, R + 0.35), mark: (end: ">"),
      stroke: 1.4pt + rgb("#c0392b"))
    content((0.8, R + 0.35), anchor: "west",
      text(size: 12pt, fill: rgb("#c0392b"))[pushed by axle])

    line(cp, (cp.at(0) + 0.7, -R), mark: (end: ">"),
      stroke: 1pt + gray)
    content((0.75, -R - 0.28), anchor: "west",
      text(size: 10pt, fill: gray)[slip tendency])

    line(cp, (cp.at(0) - 1.0, -R), mark: (end: ">"),
      stroke: 2pt + rgb("#1f6feb"))
    content((-1.05, -R + 0.28), anchor: "east",
      text(size: 13pt, fill: rgb("#1f6feb"))[$f$])
  }
})
