// Diagram: closed-open pipe with standing wave nodes/antinodes marked.
#let diagram = cetz.canvas({
  import cetz.draw: *

  let L = 5.0
  let H = 0.7   // pipe half-height

  // Pipe walls
  line((0, H), (L, H), stroke: 1.6pt)
  line((0, -H), (L, -H), stroke: 1.6pt)
  // Closed end (left cap)
  line((0, -H - 0.15), (0, H + 0.15), stroke: 2pt)
  // Open end (right, no cap)
  line((L, -H - 0.15), (L, -H), stroke: 2pt)
  line((L, H), (L, H + 0.15), stroke: 2pt)

  // 3rd harmonic standing wave for a closed-open pipe: 3/4 wavelength fits in L
  // pressure nodes at x = L, 3L/5 (antinodes at x=0, 2L/5 but shifted)
  // displacement: A sin(3pi x / 2L) — 3 quarter-waves
  let n = 50
  for i in range(n) {
    let x0 = L * i / n
    let x1 = L * (i + 1) / n
    let y0 = 0.5 * calc.sin(3 * calc.pi * x0 / (2 * L))
    let y1 = 0.5 * calc.sin(3 * calc.pi * x1 / (2 * L))
    line((x0, y0), (x1, y1), stroke: 2pt + rgb("#c0392b"))
  }

  // Node / antinode labels
  content((0, -H - 0.45), anchor: "north", text(size: 11pt)[closed\n(node)])
  content((L, -H - 0.45), anchor: "north", text(size: 11pt)[open\n(antinode)])

  // Length arrow
  line((0, -H - 1.0), (L, -H - 1.0), mark: (start: ">", end: ">"), stroke: 0.9pt)
  content((L / 2, -H - 1.35), anchor: "north", text(size: 13pt)[$L$])
})

